-- LPCFG: live-prep's live minutes of 2026-10-09, read-only. Padded past the connector's inline limit so the reply is
-- saved to a file; ../rwc_opt/scripts/grab_payload.py cuts the payload out and data/minutes_2026-10-09.json is it.
select jsonb_build_object('pad', repeat('x', 300000), 'rows', (select jsonb_agg(jsonb_build_array(to_char(minute at time zone 'UTC','HH24:MI'), left(cond,10), rate, max_spread, min_size, bid_price, bid_size, ask_price, ask_size, bid_scoring, ask_scoring, ours, others, formula_usd, pct, detail->'qBid', detail->'qAsk', detail->'lp'->>'state', (detail->'lp'->'held'->>'yes'), (detail->'lp'->'held'->>'no'), detail->'orders') order by minute, cond) from public.pm_lp_minutes where mode='live' and minute >= '2026-10-09T00:00:00Z' and minute < '2026-10-10T00:00:00Z')) payload
